// 1. Obtenemos TODOS los ítems. Si no hay ninguno, avisamos amigablemente.
const items = $input.all();

if (items.length === 0) {
  return [{ json: { error: "⚠️ No se recibieron datos. Asegúrate de ejecutar el Webhook con cURL primero." } }];
}

const item = items[0];

// 2. Verificamos si el archivo binario realmente llegó
if (!item.binary || !item.binary.data) {
  return [{ json: { error: "❌ El Webhook se ejecutó, pero no trajo un archivo binario. Revisa el comando cURL." } }];
}

// Convertimos el binario (que n8n guarda en base64) a texto plano usando Buffer nativo de Node.js
const rawText = Buffer.from(item.binary.data.data, 'base64').toString('utf8');

// 3. Definimos la configuración directamente aquí
const config = {
  strapi_url: "http://strapi:1337",
  gemini_delay_ms: 3000,
  captured_at: new Date().toISOString()
};

// 4. Palabras clave para el filtrado
const KEYWORDS = [
  "complejo","fronterizo","frontera","habilitado","cerrado","abierto",
  "suspendido","precaución","precaucion","habilitada","cerrada",
  "horario","ingreso","salida","vehículo","vehiculo","paso",
  "hrs","hora","a.m.","p.m.",
  "nevada","nieve","tormenta","temporal","viento","lluvia",
  "congelamiento","deslizamiento","alud","ruta",
  "los libertadores","cardenal","pehuenche","pircas negras",
  "jama","colchane","agua negra","vergara","pichachén","pichachen",
  "hua hum","samoré","samore","san francisco","dorotea","casas viejas",
  "san sebastián","san sebastian","bellavista","integración austral",
  "don guillermo","pino hachado","chungará","chungara","chacalluta",
  "ollague","collahuasi","portillo","río blanco",
  "atacama","coquimbo","valparaíso","valparaiso","maule",
  "biobío","biobio","araucanía","araucania","aysén","aysen",
  "magallanes","antofagasta","tarapacá","tarapaca"
];

function hasKeyword(text) {
  const lower = text.toLowerCase();
  return KEYWORDS.some(kw => lower.includes(kw));
}

// 5. Regex para capturar la estructura de WhatsApp Web
const regex = /\[(.*?)\] (.*?): ([\s\S]*?)(?=\n\[|$)/g;
let match;
let msgs = [];
let counter = 1;

while ((match = regex.exec(rawText)) !== null) {
  const timeStr = match[1]; // ej: "14:27, 14/5/2026"
  const body = match[3].trim();

  if (body.length > 10 && hasKeyword(body)) {

    const dateMatch = timeStr.match(/(\d{1,2}):(\d{2}), (\d{1,2})\/(\d{1,2})\/(\d{4})/);
    let isoDate = new Date().toISOString(); 
    let timestamp = Math.floor(Date.now() / 1000);

    if (dateMatch) {
      const hour = dateMatch[1].padStart(2, '0');
      const minute = dateMatch[2].padStart(2, '0');
      const day = dateMatch[3].padStart(2, '0');
      const month = dateMatch[4].padStart(2, '0');
      const year = dateMatch[5];

      // Forzamos la zona horaria de Chile (-04:00)
      isoDate = `${year}-${month}-${day}T${hour}:${minute}:00.000-04:00`;
      timestamp = Math.floor(new Date(isoDate).getTime() / 1000);
    }

    const msg_id = `manual_${timestamp}_${counter}`;

    msgs.push({
      json: {
        msg_id:        msg_id,
        msg_body:      body,
        msg_timestamp: timestamp,
        msg_fecha_iso: isoDate,
        msg_row_id:    null,
        msg_server_id: null,
        source_id:     "whatsapp_upf_manual",
        source_name:   "Canal WhatsApp UPF (Manual)",
        captured_at:   config.captured_at,
        strapi_url:    config.strapi_url,
        gemini_delay:  config.gemini_delay_ms
      }
    });
    counter++;
  }
}

if (msgs.length === 0) {
  return [{ json: { sin_relevantes: true, total: 0 } }];
}

// Invertimos el orden para procesar del más antiguo al más reciente
return msgs.reverse();

