const raw = $input.item.json?.output ?? $input.item.json?.text ?? $input.item.json?.content ?? "";
const msgMeta = $('Filtrar y Splitear Mensajes').item.json;

let parsed;
try {
  const cleaned = raw.replace(/```json\n?|```/g, "").trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  return [{ json: { parse_error: true, raw, ...msgMeta } }];
}

const items = parsed?.items ?? [];
if (items.length === 0) {
  return [{ json: { sin_datos: true, ...msgMeta } }];
}

return items.map(item => ({ json: { ...item, ...msgMeta } }));

const paso  = $('Buscar PasoFronterizo').item.json.data[0];
const d     = $('Parse Output Gemini').item.json;
const msgM  = $('Filtrar y Splitear Mensajes').item.json;

return [{ json: {
  payload: {
    data: {
      fecha_reporte:        d.msg_fecha_iso,
      estado_general:       d.estado ?? "desconocido",
      fuente:               "whatsapp_upf",
      mensaje_original:     d.mensaje_original ?? msgM.msg_body,
      origen_tipo:          "whatsapp_channel",
      confianza_extraccion: parseFloat(d.confianza ?? 0.5),
      id_paso:              paso.id,
      horario_apertura:     d.horario_apertura ?? null,
      horario_cierre:       d.horario_cierre ?? null,
      motivo_estado:        d.motivo_estado ?? null,
      nivel_riesgo_calc:    d.nivel_riesgo ?? null,
      tipo_vehiculos:       d.tipo_vehiculos ?? [],
      dias_operacion:       d.dias_operacion ?? [],
      msg_timestamp:        msgM.msg_timestamp,
      msg_id_waha:          msgM.msg_id,
      msg_server_id:        msgM.msg_server_id ?? null
    }
  },
  paso_nombre: paso.nombre_oficial,
  paso_id:     paso.id
}}];

// 1. Obtenemos los ítems del lote actual (ej. 5 mensajes)
const items = $input.all();

// 2. Extraemos solo los datos que Gemini necesita para trabajar
const mensajesParaGemini = items.map(item => {
  // Ojo: Tomamos los datos asumiendo que vienen del nodo "Guardar MensajeWAHA"
  // Si el mensaje ya existía, vendrá del nodo "Verificar Duplicado", ajustamos por si acaso.
  const data = item.json.data || item.json; 

  return {
    msg_id: data.msg_id_waha || data.msg_id,
    mensaje_original: data.msg_body,
    fecha_iso: data.msg_fecha_iso
  };
});

// 3. Retornamos UN SOLO ítem consolidado para gastar solo 1 llamada de Gemini
return [{
  json: {
    cantidad_en_lote: mensajesParaGemini.length,
    lote_mensajes: mensajesParaGemini
  }
}];

